import{_ as n,C as i,o as t,c as l,j as a,a as r,b as d,w as o,E as g,a2 as c,a3 as h}from"./chunks/framework.pb1iZPmZ.js";const k=JSON.parse('{"title":"14.14 System Design: Observability & Telemetry","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.14-observability-operations.md","filePath":"system-design/14.14-observability-operations.md"}'),p={name:"system-design/14.14-observability-operations.md"};function m(u,e,y,f,b,x){const s=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a("h1",{id:"_14-14-system-design-observability-telemetry",tabindex:"-1"},[r("14.14 System Design: Observability & Telemetry "),a("a",{class:"header-anchor",href:"#_14-14-system-design-observability-telemetry","aria-label":'Permalink to "14.14 System Design: Observability & Telemetry"'},"​")],-1)),(t(),d(c,null,{default:o(()=>[g(s,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20App%5BNode.js%20Express%20App%5D%20--%3E%7CStructured%20JSON%20Logs%7C%20Pino%5BPino%20Logger%20-%3E%20Elastic%20%2F%20Loki%5D%0A%20%20%20%20App%20--%3E%7COpenTelemetry%20Metrics%7C%20Prom%5BPrometheus%20-%3E%20Grafana%20Dashboard%5D%0A%20%20%20%20App%20--%3E%7CUnhandled%20Rejections%7C%20Sentry%5BSentry%20Error%20Tracking%5D%0A%20%20%20%20App%20--%3E%7CDistributed%20Trace%20Spans%7C%20Jaeger%5BJaeger%20%2F%20Zipkin%20Tracing%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=h('<hr><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Observability is the ability to understand the internal state of a software system based solely on the data it exports externally—comprising the Three Pillars: <strong>Logs</strong> (what happened), <strong>Metrics</strong> (how much / how fast), and <strong>Traces</strong> (where time was spent across hops).</p><hr><h2 id="_2-whether-and-how-this-project-uses-it" tabindex="-1">2. Whether and How THIS Project Uses It <a class="header-anchor" href="#_2-whether-and-how-this-project-uses-it" aria-label="Permalink to &quot;2. Whether and How THIS Project Uses It&quot;">​</a></h2><p>Currently, observability is <strong>Minimally Implemented</strong>:</p><ul><li>Simple <code>console.log</code> and <code>console.error</code> calls are used for connection messages and caught exceptions ([<code>app.js:14,83,105</code>](file:///Users/avishjain/avishjain9-repos/54-login-auth-portal/app.js#L14)).</li><li><strong>Gaps</strong>: No structured JSON formatting, no metric counters, no error tracking SDK (Sentry), and no distributed correlation IDs.</li></ul><hr><h2 id="_3-telemetry-pillars-tools-comparison-table" tabindex="-1">3. Telemetry Pillars &amp; Tools Comparison Table <a class="header-anchor" href="#_3-telemetry-pillars-tools-comparison-table" aria-label="Permalink to &quot;3. Telemetry Pillars &amp; Tools Comparison Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Pillar</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Selected Tool</th><th style="text-align:left;">Alternative Tool</th><th style="text-align:left;">Comparison &amp; Fit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Structured Logging</strong></td><td style="text-align:left;">Event auditing with timestamps and context</td><td style="text-align:left;"><strong>Pino (JSON)</strong></td><td style="text-align:left;">Winston</td><td style="text-align:left;">Pino is 5x faster than Winston with minimal event loop latency</td></tr><tr><td style="text-align:left;"><strong>Metrics Collection</strong></td><td style="text-align:left;">Real-time RPS, event loop lag, memory, error rates</td><td style="text-align:left;"><strong>Prometheus + prom-client</strong></td><td style="text-align:left;">Datadog</td><td style="text-align:left;">Prometheus is self-hostable on-premise without cloud data egress costs</td></tr><tr><td style="text-align:left;"><strong>Metrics Visualization</strong></td><td style="text-align:left;">Visual operational dashboards and alerts</td><td style="text-align:left;"><strong>Grafana</strong></td><td style="text-align:left;">AWS CloudWatch</td><td style="text-align:left;">Grafana provides customizable dashboards for hospital IT teams</td></tr><tr><td style="text-align:left;"><strong>Error Tracking</strong></td><td style="text-align:left;">Capturing stack traces and breadcrumbs</td><td style="text-align:left;"><strong>Sentry</strong></td><td style="text-align:left;">Bugsnag</td><td style="text-align:left;">Sentry groups duplicate errors and alerts on-call engineers instantly</td></tr><tr><td style="text-align:left;"><strong>Distributed Tracing</strong></td><td style="text-align:left;">Tracking request duration across middleware and DB</td><td style="text-align:left;"><strong>OpenTelemetry + Jaeger</strong></td><td style="text-align:left;">AWS X-Ray</td><td style="text-align:left;">Vendor-neutral industry standard for distributed span telemetry</td></tr></tbody></table><hr><h2 id="_4-key-performance-indicators-kpis-golden-signals" tabindex="-1">4. Key Performance Indicators (KPIs) &amp; Golden Signals <a class="header-anchor" href="#_4-key-performance-indicators-kpis-golden-signals" aria-label="Permalink to &quot;4. Key Performance Indicators (KPIs) &amp; Golden Signals&quot;">​</a></h2><ol><li><strong>Latency</strong>: p50, p95, and p99 response times on <code>/login</code> and <code>/dashboard</code>.</li><li><strong>Traffic</strong>: Requests per second (RPS) broken down by route.</li><li><strong>Errors</strong>: HTTP 5xx rate and failed login ratios.</li><li><strong>Saturation</strong>: Node.js event loop lag (must remain under 20ms) and MongoDB active connection pool utilization.</li></ol><hr><h2 id="_5-what-breaks-first-at-scale" tabindex="-1">5. What Breaks First at Scale <a class="header-anchor" href="#_5-what-breaks-first-at-scale" aria-label="Permalink to &quot;5. What Breaks First at Scale&quot;">​</a></h2><ul><li><strong>10x Load</strong>: Terminal console logs scroll rapidly, making manual debugging impossible.</li><li><strong>100x Load</strong>: Synchronous <code>console.log</code> blocks the event loop under heavy concurrent throughput.</li><li><strong>1000x Load</strong>: Lack of correlation IDs prevents tracing which specific database query caused a timeout spike.</li></ul><hr><h2 id="_6-senior-engineering-improvements" tabindex="-1">6. Senior Engineering Improvements <a class="header-anchor" href="#_6-senior-engineering-improvements" aria-label="Permalink to &quot;6. Senior Engineering Improvements&quot;">​</a></h2><ol><li>Replace <code>console.log</code> with <strong>Pino</strong> structured logging.</li><li>Inject a <strong>Correlation ID</strong> (<code>X-Correlation-ID</code>) on every incoming request using a UUID middleware.</li><li>Expose <code>/metrics</code> using <code>prom-client</code> and configure Grafana alerting for p99 latency exceeding 500ms.</li></ol><hr><h2 id="_7-30-second-spoken-answer" tabindex="-1">7. 30-Second Spoken Answer <a class="header-anchor" href="#_7-30-second-spoken-answer" aria-label="Permalink to &quot;7. 30-Second Spoken Answer&quot;">​</a></h2><blockquote><p>&quot;Right now, the prototype uses basic console logging. In production, I would establish the three pillars of observability: asynchronous structured JSON logging with Pino, Prometheus metrics tracking the four Golden Signals—latency, traffic, errors, and saturation—and Sentry for stack trace alerts. Every request would receive a unique correlation ID to trace issues across middleware and MongoDB queries.&quot;</p></blockquote>',22))])}const P=n(p,[["render",m]]);export{k as __pageData,P as default};
